mapper.select:
SELECT * FROM msg_send_record

    deleted = 0

        AND recipient LIKE CONCAT('%', #{recipient}, '%')


        AND channel = #{channel}


        AND send_status = #{sendStatus}


        AND biz_type = #{bizType}


        AND trigger_type = #{triggerType}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}


ORDER BY create_time DESC

SELECT COALESCE(biz_type, 'UNKNOWN') AS bizType, COUNT(*) AS totalCount, SUM(CASE WHEN send_status = 2 THEN 1 ELSE 0 END) AS successCount, SUM(CASE WHEN send_status = 3 THEN 1 ELSE 0 END) AS failedCount FROM msg_send_record WHERE deleted = 0
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY biz_type ORDER BY totalCount DESC

SELECT * FROM msg_send_record
WHERE deleted = 0
  AND biz_type = #{bizType}
  AND biz_id = #{bizId}
ORDER BY create_time DESC
